import json, pathlib, sys
paths = sys.argv[1:]
for path in paths:
    text = pathlib.Path(path).read_text(encoding="utf-8")
    if path.endswith(".jsonl"):
        rows = [json.loads(line) for line in text.splitlines() if line]
        print(path, "jsonl", len(rows), "ok")
    else:
        json.loads(text)
        print(path, "json", "ok")
